import requests
import json


class OpenHABClient:
    """Encapsulates HTTP communication with openHAB REST API."""

    def __init__(self, host, port):
        """Initialize the client with host and port."""
        self.base_url = f"http://{host}:{port}/rest"
        self.command_headers = {"Content-type": "text/plain"}
        self.polling_headers = {"Accept": "application/json"}

    def get_items(self):
        """Fetch top-level items from openHAB, returning JSON-parsed list."""
        url = f"{self.base_url}/items?recursive=false"
        try:
            response = requests.get(url, headers=self.polling_headers, timeout=5)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException:
            return None

    def get_item_state(self, item_name):
        """Fetch the state of a specific item, returning string or None on error."""
        url = f"{self.base_url}/items/{item_name}/state"
        try:
            response = requests.get(url, headers=self.command_headers, timeout=5)
            if response.status_code == 200:
                return response.text.strip()
            else:
                return None
        except requests.exceptions.RequestException:
            return None

    def send_command(self, item_name, command):
        """Send a command to an item, returning HTTP status code (e.g., 200, 404)."""
        url = f"{self.base_url}/items/{item_name}"
        try:
            response = requests.post(url, data=str(command), headers=self.command_headers, timeout=5)
            return response.status_code
        except requests.exceptions.RequestException:
            return 0

    def set_state(self, item_name, state):
        """Set the state of an item, returning HTTP status code (e.g., 200, 404)."""
        url = f"{self.base_url}/items/{item_name}/state"
        try:
            response = requests.put(url, data=str(state), headers=self.command_headers, timeout=5)
            return response.status_code
        except requests.exceptions.RequestException:
            return 0
